-- Authored content: original texts filling gaps the open textbooks do not cover.
-- Everything is origin='ai_generated' - there is no source to quote.
-- Written as plain independent statements, no nested CTEs: that is the shape
-- the Supabase SQL editor is known to accept for this project.

insert into public.content_sources (title, author, source_url, license, license_url, parser, parser_config, status)
values ('Yuny authored content (English)', 'Yuny', 'yuny://authored/en/v1', 'Proprietary - Yuny original content, not an open educational resource', null, 'authored', '{}'::jsonb, 'ready')
on conflict (source_url) do update set status = 'ready', license = excluded.license;

-- ===== Booking a place to stay (A2) =====
insert into public.content_units (source_id, external_id, kind, title, position, parsed_blocks, parsed_at, word_count, status, cefr_level)
values ((select id from public.content_sources where source_url = 'yuny://authored/en/v1'), 'authored-booking-a-room', 'chapter', 'Booking a place to stay', 0, '[{"type":"paragraph","text":"Marta wants to visit Lisbon in April. She has five days and a small budget, so she looks for a cheap place to stay."},{"type":"paragraph","text":"First she opens a booking website. She types the city and the dates. The website shows hotels, hostels and apartments."},{"type":"paragraph","text":"A hotel near the centre costs 120 euros a night. That is too expensive for Marta."},{"type":"paragraph","text":"A hostel costs 25 euros a night, but she must share a room with five other people. Marta does not sleep well when a room is noisy."},{"type":"paragraph","text":"Then she finds a small guesthouse. It costs 45 euros a night. The room is private and breakfast is included. The guesthouse is twenty minutes from the centre by bus."},{"type":"paragraph","text":"Marta reads the reviews. Other guests write that the beds are comfortable and the owner is friendly. One guest writes that the walls are thin."},{"type":"paragraph","text":"She decides to book the guesthouse for four nights. She pays with her card and receives an email. The email is her confirmation."},{"type":"paragraph","text":"Marta prints the confirmation. She wants to show it when she arrives."}]'::jsonb, now(), 177, 'parsed', 'A2'::public.cefr_level)
on conflict (source_id, external_id) do update set parsed_blocks = excluded.parsed_blocks, word_count = excluded.word_count, cefr_level = excluded.cefr_level, title = excluded.title;
