-- ===== Checking in at the hotel (A2) =====
insert into public.content_units (source_id, external_id, kind, title, position, parsed_blocks, parsed_at, word_count, status, cefr_level)
values ((select id from public.content_sources where source_url = 'yuny://authored/en/v1'), 'authored-checking-in', 'chapter', 'Checking in at the hotel', 1, '[{"type":"paragraph","text":"Marta arrives in Lisbon on Friday afternoon. She takes a bus from the airport and walks to the guesthouse."},{"type":"paragraph","text":"A man is standing behind the desk. \"Good afternoon. Do you have a reservation?\" he asks."},{"type":"paragraph","text":"\"Yes,\" says Marta. \"My name is Marta Silva. I booked a single room for four nights.\""},{"type":"paragraph","text":"The man looks at his computer. \"I have it here. Can I see your passport, please?\""},{"type":"paragraph","text":"Marta gives him her passport. He writes down the number and gives it back."},{"type":"paragraph","text":"\"Your room is number 12, on the second floor. Here is the key. Breakfast is from seven until ten in the small room next to the entrance.\""},{"type":"paragraph","text":"\"Thank you. What time do I have to leave on Tuesday?\" Marta asks."},{"type":"paragraph","text":"\"Check-out is at eleven o''clock. If you need a later time, please tell us the day before.\""},{"type":"paragraph","text":"Marta takes her key and goes upstairs. The room is small but clean, and the window looks out over a narrow street."}]'::jsonb, now(), 160, 'parsed', 'A2'::public.cefr_level)
on conflict (source_id, external_id) do update set parsed_blocks = excluded.parsed_blocks, word_count = excluded.word_count, cefr_level = excluded.cefr_level, title = excluded.title;
