-- ===== Asking for directions (A2) =====
insert into public.content_units (source_id, external_id, kind, title, position, parsed_blocks, parsed_at, word_count, status, cefr_level)
values ((select id from public.content_sources where source_url = 'yuny://authored/en/v1'), 'authored-asking-directions', 'chapter', 'Asking for directions', 2, '[{"type":"paragraph","text":"On Saturday morning Marta wants to visit the castle. She has a paper map, but the streets are narrow and she quickly gets lost."},{"type":"paragraph","text":"She stops an older woman near a bakery. \"Excuse me, how do I get to the castle?\""},{"type":"paragraph","text":"\"It is not far,\" the woman says. \"Go straight along this street to the end. Then turn left at the church.\""},{"type":"paragraph","text":"\"Left at the church,\" Marta repeats."},{"type":"paragraph","text":"\"Yes. After the church you will see some steps. Go up the steps and turn right. The castle is at the top of the hill.\""},{"type":"paragraph","text":"\"Is it far on foot?\""},{"type":"paragraph","text":"\"About fifteen minutes, but the hill is steep. If you are tired, you can take tram 28. The stop is behind you, opposite the pharmacy.\""},{"type":"paragraph","text":"Marta thanks her and decides to walk. She goes straight, turns left at the church and finds the steps."},{"type":"paragraph","text":"Twenty minutes later she is standing at the castle wall, looking down at the red roofs of the city."}]'::jsonb, now(), 161, 'parsed', 'A2'::public.cefr_level)
on conflict (source_id, external_id) do update set parsed_blocks = excluded.parsed_blocks, word_count = excluded.word_count, cefr_level = excluded.cefr_level, title = excluded.title;
insert into public.knowledge_items (content_unit_id, kind, dedup_key, data, origin, status)
