-- ===== A problem with the room (B1) =====
insert into public.content_units (source_id, external_id, kind, title, position, parsed_blocks, parsed_at, word_count, status, cefr_level)
values ((select id from public.content_sources where source_url = 'yuny://authored/en/v1'), 'authored-problem-with-room', 'chapter', 'A problem with the room', 3, '[{"type":"paragraph","text":"On the second night Marta hardly slept. The guests in the next room came back after midnight and talked loudly until three in the morning. The guest who had warned about thin walls in the review had not been exaggerating."},{"type":"paragraph","text":"At breakfast she thought about what to do. She could say nothing and hope the next night would be quieter, or she could complain. She had never enjoyed complaining, but four nights of no sleep would ruin the trip."},{"type":"paragraph","text":"She went to the desk and explained the problem calmly. \"I understand it is not your fault,\" she said, \"but I have not slept properly since I arrived. Is there another room available?\""},{"type":"paragraph","text":"The receptionist checked the computer and apologised. The guesthouse was full that night, but a room at the back would be free from the following afternoon. It was slightly smaller and had no view, though it was much quieter."},{"type":"paragraph","text":"\"I would rather have a quiet room than a view,\" Marta said."},{"type":"paragraph","text":"He moved her booking and offered her a free breakfast for the trouble. If she had said nothing, she would have spent three more bad nights."},{"type":"paragraph","text":"Later she added her own review. She wrote that the walls were thin, but that the staff had solved the problem quickly and politely. Both parts of that, she thought, were worth knowing."}]'::jsonb, now(), 222, 'parsed', 'B1'::public.cefr_level)
on conflict (source_id, external_id) do update set parsed_blocks = excluded.parsed_blocks, word_count = excluded.word_count, cefr_level = excluded.cefr_level, title = excluded.title;
