-- ===== Buying a train ticket (B1) =====
insert into public.content_units (source_id, external_id, kind, title, position, parsed_blocks, parsed_at, word_count, status, cefr_level)
values ((select id from public.content_sources where source_url = 'yuny://authored/en/v1'), 'authored-buying-a-ticket', 'chapter', 'Buying a train ticket', 4, '[{"type":"paragraph","text":"Marta had planned to spend her last full day in Sintra, a town about forty minutes from Lisbon by train. She reached the station early, expecting a queue, and found one."},{"type":"paragraph","text":"The machines took cards but only sold single tickets, and the screen was in Portuguese. Rather than guess, she joined the shorter queue at the ticket office."},{"type":"paragraph","text":"\"A return to Sintra, please. Is there a cheaper option if I come back this evening?\""},{"type":"paragraph","text":"\"A day return is cheaper than two singles,\" the clerk said. \"It is valid until midnight, but only on regional trains. If you take an express, you will have to pay a supplement.\""},{"type":"paragraph","text":"Marta bought the day return. The clerk pointed at the departure board and told her that trains left every twenty minutes from platform four."},{"type":"paragraph","text":"She had almost boarded the wrong train when a guard stopped her: that one went to Cascais. The two lines leave from the same platform, and the difference is easy to miss unless you check the board carefully."},{"type":"paragraph","text":"By the time she found the right train, she had learned something useful. Asking a person had cost her five minutes in a queue and saved her a wasted afternoon."}]'::jsonb, now(), 199, 'parsed', 'B1'::public.cefr_level)
on conflict (source_id, external_id) do update set parsed_blocks = excluded.parsed_blocks, word_count = excluded.word_count, cefr_level = excluded.cefr_level, title = excluded.title;
insert into public.knowledge_items (content_unit_id, kind, dedup_key, data, origin, status)
values ((select cu.id from public.content_units cu where cu.source_id = (select id from public.content_sources where source_url = 'yuny://authored/en/v1') and cu.external_id = 'authored-buying-a-ticket'), 'topic', 'transport-and-directions', '{"label":"transport-and-directions"}'::jsonb, 'ai_generated', 'draft')
